package com.receiptledger.v1.price;

import com.receiptledger.v1.item.*;import com.receiptledger.v1.persistence.*;import com.receiptledger.v1.product.*;import com.receiptledger.v1.validation.*;import java.util.*;

public final class PriceHistoryService {
 private final ReceiptStore receipts;private final ProductCatalogStore catalog;public PriceHistoryService(ReceiptStore receipts,ProductCatalogStore catalog){this.receipts=receipts;this.catalog=catalog;}
 public PriceHistory history(String productId){CatalogProduct product=catalog.product(productId);if(product==null)throw new IllegalArgumentException("unknown product");List<PriceObservation> out=new ArrayList<>();for(ItemLinkRef ref:catalog.linksForProduct(productId)){ReceiptRecord r=receipts.get(ref.receiptId);if(r==null||!(r.validationStatus==ValidationStatus.PASS||r.validationStatus==ValidationStatus.PASS_WITH_WARNINGS))continue;PersistedItem item=find(r.items,ref.itemOrdinal);if(item==null)continue;Long price=item.unitPrice;ValueOrigin origin=item.unitPriceOrigin;if(price==null&&item.quantity!=null&&item.quantity>0&&item.lineAmount!=null&&item.lineAmount%item.quantity==0){price=item.lineAmount/item.quantity;origin=ValueOrigin.INFERRED_ARITHMETIC;}if(price==null||price<0)continue;out.add(new PriceObservation(r.id,r.purchaseDate,r.storeName,r.createdAtMillis,item.name,price,item.quantity,item.lineAmount,origin,ref.source,r.validationStatus));}Collections.sort(out,(a,b)->{String ad=a.purchaseDate,bd=b.purchaseDate;if(ad!=null&&bd!=null){int c=bd.compareTo(ad);if(c!=0)return c;}else if(ad!=null)return -1;else if(bd!=null)return 1;return Long.compare(b.createdAtMillis,a.createdAtMillis);});boolean comparable=product.type==ProductType.STANDARD;if(out.isEmpty())return new PriceHistory(product,comparable,out,null,null,null,null);long latest=out.get(0).unitPrice;if(!comparable)return new PriceHistory(product,false,out,latest,null,null,null);long min=Long.MAX_VALUE,max=Long.MIN_VALUE,sum=0;for(PriceObservation o:out){min=Math.min(min,o.unitPrice);max=Math.max(max,o.unitPrice);sum+=o.unitPrice;}return new PriceHistory(product,true,out,latest,min,max,Math.round((double)sum/out.size()));}
 private static PersistedItem find(List<PersistedItem> items,int ordinal){for(PersistedItem i:items)if(i.ordinal==ordinal)return i;return null;}
}
